NAN = float("nan")
_LOCAL_TZ = timezone(timedelta(hours=8))   # injection.json 用 +08:00 本地表示
_OPENER = urllib.request.build_opener(urllib.request.ProxyHandler({}))


def now_iso():
    """ISO8601 + ms + Z（UTC）。"""
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.") + \
        f"{datetime.now(timezone.utc).microsecond // 1000:03d}Z"


def _dt_iso(dt):
    return dt.strftime("%Y-%m-%dT%H:%M:%S.") + f"{dt.microsecond // 1000:03d}Z"


def _parse_iso(s):
    """解析 _dt_iso 产出的 ...Z(UTC) 串 → aware datetime。失败返回 None。"""
    if isinstance(s, datetime):
        return s
    if not isinstance(s, str):
        return None
    for fmt in ("%Y-%m-%dT%H:%M:%S.%fZ", "%Y-%m-%dT%H:%M:%SZ"):
        try:
            return datetime.strptime(s, fmt).replace(tzinfo=timezone.utc)
        except Exception:
            continue
    return None


def _dt_iso_local(s_or_dt):
    """转 +08:00 本地表示(injection.json 用)。接受 ISO Z 串或 datetime。None→None。"""
    if s_or_dt is None:
        return None
    dt = _parse_iso(s_or_dt) if isinstance(s_or_dt, str) else s_or_dt
    if dt is None:
        return None
    loc = dt.astimezone(_LOCAL_TZ)
    return loc.strftime("%Y-%m-%dT%H:%M:%S.") + f"{loc.microsecond // 1000:03d}+08:00"


# M8 增量0b: 3-window(triple T3/T4)合法 membership 标签全集(fail-closed 断言用)。
#   仅当 f3win 双端实窗时 membership_for 走 9-way 路径并断言产出 ∈ 此集; dual/2-window 路径不触及本集。
TRIPLE_MEMBERSHIP_LABELS = frozenset({
    "baseline", "recovery",
    "F1_only", "F2_only", "F3_only",
    "F1F2", "F1F3", "F2F3", "F1F2F3",
})


def membership_for(ts, f1win, f2win, f3win=None):
    """逐记录窗归属(对齐上游 5-way): overlap / F1_only / F2_only / baseline(ts 早于所有在场故障 start) / recovery(故障 start 后但不在任何窗)。
    上游 Membership(): baseline iff t<f1s and t<f2s, else recovery。窗任一端为 None → 该轴视为未命中(start 视为 -inf)。
    nested 下 overlap==内含根窗(无论 F2⊂F1 或 F1⊂F2), 仅无被含根的 only 桶(14/15 F2⊂F1→无 F2_only; host_cpu_xsvccpu 唯一反向 F1⊂F2→无 F1_only);单根因 F2 缺席→baseline/recovery 分界只看 F1。〔R3 re-audit BLOCKER 修:原 else 无条件 baseline 把 post-fault 误标 baseline → 上游按 membership 分桶会 corrupt;M4 eval 不受影响(feature-view 排除 baseline+recovery),但 raw 对齐需此修 + 存量 27 case re-tag(见 M4b spec §10 M5 worklist)〕
    M8 增量0b(3-window triple): f3win=None 或端点不全(含 [None,None] / [dt,None]) → 逐字走上述 5-label 2-window 路径(对任意 ts 与 pre-0b byte-identical)。仅当 f3win **双端实窗** → 9-way 分桶: baseline / recovery / F1_only / F2_only / F3_only / F1F2 / F1F3 / F2F3 / F1F2F3, 产出 fail-closed 断言 ∈ TRIPLE_MEMBERSHIP_LABELS。★注(T2 建后修正): **所有 triple(T2/T1/T3/T4)给 write_case 传【真 3-窗 f3win】走 9-way**(满足审计 BLOCKER: 3 cgt = 3 真 fault 窗; T2 RES∥DEP 共活→F1F2, +CFG→F1F2F3)。守卫仍防御性接受 None/[None,None](dual/single 默认走此), 故不加 'triple⇒f3win 非空' 硬断言。★【与 write_case 3-窗解耦的 2-窗视图是 gate 自己内部的】: 如 deep_triple_res_dep_cfg_gate 自算 blob 后调 membership_for(ts, blob, cfg) 只传 2 窗 → gate 用 F1_only/overlap 判 per-root; 这不改变 write_case 的 9-way raw 分桶。"""
    def _in(win):
        if not win or win[0] is None or win[1] is None or ts is None:
            return False
        return win[0] <= ts <= win[1]
    if f3win is None or not all(f3win):
        # --- 5-label 2-window 路径(pre-0b verbatim): dual / single / 2-window triple(T2/T1) ---
        in_f1 = _in(f1win)
        in_f2 = _in(f2win)
        if in_f1 and in_f2:
            return "overlap"
        if in_f1:
            return "F1_only"
        if in_f2:
            return "F2_only"
        # 不在任何故障窗:对齐上游 baseline(ts<所有在场故障 start)/ recovery(之后)。缺席轴 start 视为 -inf。
        def _start(win):
            return win[0] if (win and win[0] is not None) else None
        f1s, f2s = _start(f1win), _start(f2win)
        before_f1 = (f1s is None) or (ts < f1s)
        before_f2 = (f2s is None) or (ts < f2s)
        if before_f1 and before_f2:
            return "baseline"
        return "recovery"
    # --- 9-way 3-window 路径(f3win 双端实窗, triple T3/T4) ---
    in_f1 = _in(f1win)
    in_f2 = _in(f2win)
    in_f3 = _in(f3win)
    if in_f1 and in_f2 and in_f3:
        label = "F1F2F3"
    elif in_f1 and in_f2:
        label = "F1F2"
    elif in_f1 and in_f3:
        label = "F1F3"
    elif in_f2 and in_f3:
        label = "F2F3"
    elif in_f1:
        label = "F1_only"
    elif in_f2:
        label = "F2_only"
    elif in_f3:
        label = "F3_only"
    else:
        # 不在任何故障窗:baseline(ts<所有在场故障 start)/ recovery(之后)。缺席轴 start 视为 -inf。
        def _start(win):
            return win[0] if (win and win[0] is not None) else None
        f1s, f2s, f3s = _start(f1win), _start(f2win), _start(f3win)
        before_f1 = (f1s is None) or (ts < f1s)
        before_f2 = (f2s is None) or (ts < f2s)
        before_f3 = (f3s is None) or (ts < f3s)
        label = "baseline" if (before_f1 and before_f2 and before_f3) else "recovery"
    assert label in TRIPLE_MEMBERSHIP_LABELS, f"triple membership label illegal: {label!r}"
    return label


def _overlap_window(f1win, f2win):
    """F1∩F2 时序交集(nested 下 == 被含根窗(14/15 F2⊂F1→==F2 窗; host_cpu_xsvccpu F1⊂F2→==F1 窗即 host 窗))。任一窗不全 → None。"""
    if not (f1win and f2win and all(f1win) and all(f2win)):
        return None
    start = max(f1win[0], f2win[0])
    end = min(f1win[1], f2win[1])
    if start > end:
        return None
    return {"start": _dt_iso(start), "end": _dt_iso(end),
            "duration_seconds": round((end - start).total_seconds(), 2)}


def _triple_overlap_windows(f1win, f2win, f3win):
    """M8 增量0b: triple(3-window)四格 overlap-lattice — 3 个 pairwise 交 + 1 个三交。
    pairwise 3 格复用 _overlap_window(不改其行为; 任一窗不全→该格 None);
    三交 F1F2F3: start=max(3 起), end=min(3 止), 任一窗不全或 start>end → None。"""
    def _three_way():
        for w in (f1win, f2win, f3win):
            if not (w and all(w)):
                return None
        start = max(f1win[0], f2win[0], f3win[0])
        end = min(f1win[1], f2win[1], f3win[1])
        if start > end:
            return None
        return {"start": _dt_iso(start), "end": _dt_iso(end),
                "duration_seconds": round((end - start).total_seconds(), 2)}
    return {
        "F1F2": _overlap_window(f1win, f2win),
        "F1F3": _overlap_window(f1win, f3win),
        "F2F3": _overlap_window(f2win, f3win),
        "F1F2F3": _three_way(),
    }


def _span_is_5xx(span):
    """span 是否带 5xx/504 指纹(http.status_code>=500 或 error=true / otel status ERROR)。"""
    for t in span.get("tags", []) or []:
        k = (t.get("key") or "")
        v = t.get("value")
        if "status_code" in k:
            try:
                if int(v) >= 500:
                    return True
            except Exception:
                pass
        if k == "error" and (v is True or str(v).lower() == "true"):
            return True
        if k == "otel.status_code" and str(v).upper() == "ERROR":
            return True
    return False


def build_root_metric_contract(evidence, fault="dual_timeout_retry"):
    """root_metric_contract 对象; notes 承重串一份三处复用(metadata + validation #4 + #5)。按 fault 串证据。"""
    if fault == "net_delay_single":
        # 单根因(M2b-1): 只产 F1 contract(无 F2), valid 只看 F1。
        notes = (f"net_delay_points={evidence.get('net_delay_points')};"
                 f"f1_only_p95_shift_ms={evidence.get('f1_only_p95_shift_ms')};"
                 f"baseline_p95_ms={evidence.get('baseline_p95_ms')};"
                 f"F1_only_ok_ratio={evidence.get('F1_only_ok_ratio')}")
        return {
            "F1": bool(evidence["per_root_F1"]),
            "valid": bool(evidence["per_root_F1"]),
            "notes": notes,
        }
    if fault == "net_loss_single":
        # 单根因(M2b-1b): 只产 F1 contract(无 F2); loss 合法 error → error_ratio 作 loss-vs-delay 判别证据。
        notes = (f"net_loss_points={evidence.get('net_loss_points')};"
                 f"f1_only_p95_shift_ms={evidence.get('f1_only_p95_shift_ms')};"
                 f"baseline_p95_ms={evidence.get('baseline_p95_ms')};"
                 f"f1_only_error_ratio={evidence.get('f1_only_error_ratio')}")
        return {
            "F1": bool(evidence["per_root_F1"]),
            "valid": bool(evidence["per_root_F1"]),
            "notes": notes,
        }
    if fault == "pod_failure_single":
        # 单根因(M2b-2): 可用率故障 = error 主导; notes 带窗有效性(restart_delta/chaos_induced_restart, main 注入 evidence)。
        notes = (f"F1_only_error_ratio={evidence.get('F1_only_error_ratio')};"
                 f"F1_only_ok_ratio={evidence.get('F1_only_ok_ratio')};"
                 f"restart_delta={evidence.get('restart_delta')};"
                 f"chaos_induced_restart={evidence.get('chaos_induced_restart')};"
                 f"catalog_ready_dropped={evidence.get('catalog_ready_dropped')}")
        return {
            "F1": bool(evidence["per_root_F1"]),
            "valid": bool(evidence["per_root_F1"]),
            "notes": notes,
        }
    if fault == "runtime_exception_single":
        # 单根因(M2b3 RUN): app env-hook 运行时异常 = error 主导(复用 pod_failure 判据 F1_only_error_ratio≥0.8); 只产 F1 contract(无 F2)。
        notes = (f"F1_only_error_ratio={evidence.get('F1_only_error_ratio')};"
                 f"F1_only_ok_ratio={evidence.get('F1_only_ok_ratio')};"
                 f"chaos_engine=app_env_hook;env=FAULT_RAISE=1")
        return {
            "F1": bool(evidence["per_root_F1"]),
            "valid": bool(evidence["per_root_F1"]),
            "notes": notes,
        }
    if fault == "service_cpu_single":
        # 单根因(M3a S3): 只产 F1 contract(无 F2); service CPU 慢非失败 → carrier p95 RELATIVE ratio 作主证据。
        notes = (f"f1_only_p95_ratio={evidence.get('f1_only_p95_ratio')};"
                 f"baseline_p95_ms={evidence.get('baseline_p95_ms')};"
                 f"f1_only_p95_ms={evidence.get('f1_only_p95_ms')};"
                 f"F1_only_ok_ratio={evidence.get('F1_only_ok_ratio')}")
        return {
            "F1": bool(evidence["per_root_F1"]),
            "valid": bool(evidence["per_root_F1"]),
            "notes": notes,
        }
