def apply_catalog_bad():
    """apply 11b-catalog-bad.yaml(慢 primary FAULT_DELAY_MS=2000) + 等 rollout。返回 bool(applied)。"""
    cp = subprocess.run([KUBECTL, "apply", "-f", CATALOG_BAD_YAML],
                        capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=60)
    print(f"  [catalog-bad] apply rc={cp.returncode} {cp.stdout.strip()} {cp.stderr.strip()}", flush=True)
