def _wait_carrier_code(carrier_url, want_code, timeout_s=150, confirm=3, interval=2.0, label=""):
    """轮询 carrier_url 直到连续 confirm 次返回 HTTP want_code(或超时)。返回稳定命中的 ISO Z 时刻(streak 首命中); 超时返回 now_iso() 兜底。
    ★RUN 窗对齐(live 标定 2026-07-01, run_smoke_01): kubectl set env 触发 catalog rollout, port-forward(deploy/catalog)重路由到新 pod
      有 ~50s 滞后, 且 `rollout status` 会提前返回(~14s)→ 若用 rollout 返回时刻做 injected_at, during 窗错位(500 全落 post 窗, F1_only_error=0.25 挂门)。
      故 RUN 的 injected_at/recovered_at 改取【carrier 实际稳定观测到 500/200】时刻, 使 fault 窗与可观测故障对齐(harness-无关, 不赌 port-forward 内部时序)。"""
    streak = 0
    streak_start_ts = None
    max_iters = int(timeout_s / interval) + 1
    for i in range(max_iters):
        try:
            _dur, _ok, code = probe_carrier(carrier_url, timeout=4)
        except Exception:
            code = None
        if code == want_code:
            if streak == 0:
                streak_start_ts = now_iso()
            streak += 1
            if streak >= confirm:
                print(f"  [runtime-exc] carrier 稳定观测 HTTP {want_code}(连 {confirm} 次)@~{int(i*interval)}s {label}", flush=True)
                return streak_start_ts
        else:
            streak = 0
            streak_start_ts = None
        time.sleep(interval)
    print(f"  [WARN][runtime-exc] {int(timeout_s)}s 内未连续观测到 HTTP {want_code}({label}) → 窗对齐兜底用 now()", flush=True)
    return now_iso()


def _wait_carrier_slow(carrier_url, want_slow_ms, timeout_s=150, confirm=3, interval=2.0,
                       want_fast=False, label=""):
    """轮询 carrier_url 直到连续 confirm 次观测到【延迟态】(或超时)。返回稳定命中的 ISO Z 时刻(streak 首命中); 超时返回 now_iso() 兜底。
    ★DK11 net_delay_x_inv_latency 窗对齐(镜像 _wait_carrier_code, 唯一区别=匹配判据): latency 类故障无 HTTP 状态翻转(慢成功仍 200),
      故不能用 _wait_carrier_code(状态码翻转)对齐窗, 改用【成功且延迟超/低于阈】判据。
    - want_fast=False(默认, 注入->慢): probe ok 且 dur >= want_slow_ms 视为命中(carrier 稳定观测到延迟态 = 故障就位);
    - want_fast=True(恢复->快): probe ok 且 dur <  want_slow_ms 视为命中(carrier 稳定观测到快速态 = 故障解除)。
    要求连续 confirm 次命中(streak); 与 _wait_carrier_code 同款 rollout/port-forward ~50s 滞后兜底(不赌内部时序)。
    probe timeout=max(4, int(want_slow_ms/1000)+2)(至少给 want_slow_ms + 2s headroom, 防 probe 自身超时误判 error)。"""
    streak = 0
    streak_start_ts = None
    _to = max(4, int(want_slow_ms / 1000) + 2)
    max_iters = int(timeout_s / interval) + 1
    for i in range(max_iters):
        try:
            dur, ok, _code = probe_carrier(carrier_url, timeout=_to)
        except Exception:
            dur, ok = 0.0, False
        matched = bool(ok and (dur < want_slow_ms if want_fast else dur >= want_slow_ms))
        if matched:
            if streak == 0:
                streak_start_ts = now_iso()
            streak += 1
            if streak >= confirm:
                _dir = "fast(<%d ms)" % want_slow_ms if want_fast else "slow(>=%d ms)" % want_slow_ms
                print(f"  [wait-slow] carrier 稳定观测 {_dir}(连 {confirm} 次)@~{int(i*interval)}s {label}", flush=True)
                return streak_start_ts
        else:
            streak = 0
            streak_start_ts = None
        time.sleep(interval)
    _dir = "fast" if want_fast else "slow"
    print(f"  [WARN][wait-slow] {int(timeout_s)}s 内未连续观测到 {_dir}(thr={want_slow_ms}ms, {label}) → 窗对齐兜底用 now()", flush=True)
    return now_iso()


def inject_runtime_exception(ops_log, carrier_url):
    """注 F1(runtime_exception): kubectl set env deploy/catalog FAULT_RAISE=1 → catalog before_request 抛 RuntimeError → /api/* 全 500。
    injected_at 取【carrier 稳定观测到 500】时刻(见 _wait_carrier_code: rollout/port-forward ~50s 滞后, 不用 rollout status 返回时刻)。返回 injected_at ISO Z。"""
    cp = _kubectl(["set", "env", f"deploy/{CATALOG_DEPLOY}", "FAULT_RAISE=1"], timeout=30)
    _kubectl(["rollout", "status", f"deploy/{CATALOG_DEPLOY}", "--timeout=120s"], timeout=130)
    ts = _wait_carrier_code(carrier_url, 500, label="inject->500")
    ops_log.append({"ts": ts, "op": "inject_runtime_exception", "deploy": CATALOG_DEPLOY,
                    "env": "FAULT_RAISE=1", "rc": cp.returncode, "engine": "app_env_hook(kubectl set env)",
                    "window_aligned_to": "carrier_observed_500"})
    print(f"  [runtime-exc] set env FAULT_RAISE=1 deploy/{CATALOG_DEPLOY} rc={cp.returncode} injected_at(obs500)={ts}", flush=True)
    return ts


def recover_runtime_exception(ops_log, carrier_url):
    """恢复 F1(runtime_exception): kubectl set env deploy/catalog FAULT_RAISE-(unset)。recovered_at 取【carrier 稳定观测到 200】时刻
    (同 inject 窗对齐, ~46s 滞后)→ 保证 post 窗干净(无残留 500)。返回 recovered_at ISO Z。"""
    cp = _kubectl(["set", "env", f"deploy/{CATALOG_DEPLOY}", "FAULT_RAISE-"], timeout=30)
    _kubectl(["rollout", "status", f"deploy/{CATALOG_DEPLOY}", "--timeout=120s"], timeout=130)
    ts = _wait_carrier_code(carrier_url, 200, label="recover->200")
    ops_log.append({"ts": ts, "op": "recover_runtime_exception", "deploy": CATALOG_DEPLOY,
                    "env": "FAULT_RAISE-", "rc": cp.returncode, "window_aligned_to": "carrier_observed_200"})
    print(f"  [runtime-exc] unset env FAULT_RAISE deploy/{CATALOG_DEPLOY} rc={cp.returncode} recovered_at(obs200)={ts}", flush=True)
    return ts


