    cp = subprocess.run([KUBECTL, "apply", "-f", STRESSOR_DEPLOY_YAML],
                        capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=60)
    print(f"  [stressor] apply deploy rc={cp.returncode} {cp.stdout.strip()} {cp.stderr.strip()}", flush=True)
