    _kubectl(["scale", f"deploy/{STRESSOR_DEPLOY}", "--replicas=1"], timeout=30)
    rs = _kubectl(["rollout", "status", f"deploy/{STRESSOR_DEPLOY}", "--timeout=90s"], timeout=100)
    print(f"  [stressor] scale 1 + rollout (rc={rs.returncode})", flush=True)
    # 3) apply StressChaos cpu(workers=12) + 等 AllInjected(复用 apply_chaos_crd kind=stresschaos)
