    # retro-S3(M3b-2, spec §193 deliverable): service_cpu_single 加 service_cpu_throttle_present validation(仅 service_cpu case)。
    #   ★ SOFT/None-tolerant(像 vm_cpu_saturated/catalog_server_p95_flat): 高饱和 scrape gappy → throttle None/EMPTY → degraded(不阻 release);
    #     有值且 spike>eps → pass(真验, probe2 实测 0→1.14)。**绝不让已 live 验通的 service_cpu_single 从 ready 变 not-ready**。
    if fault == "service_cpu_single":
        _thr = gate_evidence.get("service_cpu_throttle_max")
        _thr_present = bool(_thr is not None and _thr > THROTTLE_EPS)
        validation_results.append({
            "id": "service_cpu_throttle_present",
            "status": "pass" if _thr_present else "degraded",
            "notes": "catalog cfs_throttle during spike(post-hoc, container_cpu_cfs_throttled_seconds_total): "
                     "catalog 500m cgroup quota 命中=容器级根信号(probe2 实测 0→1.14)。"
                     "SOFT/None-tolerant(高饱和 scrape gappy 可能 None/EMPTY → degraded 不阻 release, 像 vm_cpu_saturated; 仅有值时验 spike>eps), "
                     "绝不并入 gate per_root_F1(不破坏现有 p95-ratio ready 逻辑); confinement(其它 pod CPU flat)best-effort 旁证。",
            "detail": {"service_cpu_throttle_max": _thr,
                       "service_cpu_throttle_by_pod": gate_evidence.get("service_cpu_throttle_by_pod"),
                       "throttle_eps": THROTTLE_EPS,
                       "confinement_other_pod_cpu_max": gate_evidence.get("confinement_other_pod_cpu_max")},
        })
    # degraded(catalog_server_p95_flat / pod_failure_window_validity / service_cpu_throttle_present / cfg_validity_footprint 项)视为可发布
    #   (service-level/留 live 核/throttle soft None-tolerant/AUDIT-FIX cfg-validity fail 只驱动 hedge); 其余项须 pass。
    all_validation_pass = all(
        v["status"] == "pass"
        or (v["id"] in ("catalog_server_p95_flat", "pod_failure_window_validity",
                        "service_cpu_throttle_present", "cfg_validity_footprint") and v["status"] == "degraded")
        for v in validation_results)

    during = next(s for s in stages if s["stage"] == "during_fault")
    pre = next(s for s in stages if s["stage"] == "pre_fault")
    post = next(s for s in stages if s["stage"] == "post_recovery")

    ground_truth = {
        "answer_type": answer_type, "root_count": root_count,
        "fault_category": profile["fault_category"],
        "composition_type": profile["composition_type"],
        "interaction_pattern": profile["interaction_pattern"],
        "root_cause_services": profile["root_cause_services"],
        "root_cause_instances": profile["root_cause_instances"],
        "affected_services": affected_services,
        "fault_types": profile["fault_types"],
        "injection_faults": profile["injection_faults"],
        "component_ground_truth": component_ground_truth,
        "component_fault_windows": component_fault_windows,
        "overlap_window": overlap_window,
    }
    if overlap_windows is not None:
        ground_truth["overlap_windows"] = overlap_windows   # M8 增量0b: 仅 3-window triple 追加
    # ★DK09 口径A hedge 旗标(AUDIT-FIX MINOR-3, 机器可读): cfg-validity 臂 fail 不挡落盘(validity 只驱动 hedge),
    #   但 F2 无独立业务遥测足迹 → 下游按 interaction_pattern_hedged 过滤此类 case;
    #   5 维 label 本就 PROVISIONAL(待上游 24-combo 校准), fallback 与 SUMMARY hedge 文案一致(masking/config-state-only)。
    if fault == "host_cpu_x_cfg_timeout" and (
            (gate_evidence.get("cfg_validity_footprint") or {}).get("validity_pass") is False):
        ground_truth["interaction_pattern_hedged"] = True
        ground_truth["interaction_pattern_fallback"] = "masking/config-state-only"
    if off_graph_meta:
        ground_truth["off_graph_metadata"] = off_graph_meta   # M3b S1 off-graph 共因(非 5 维关系维)

    # config(per-fault: NET 加 delay/connect; M1 加 timeout 预算)
    config = {"stage_seconds": args.stage_seconds, "poll": args.poll, "carrier_item": args.item,
              "fault": fault, "f2_offset_seconds": args.f2_offset_seconds,
              "f2_duration_seconds": args.f2_duration_seconds}
    if fault == "net_delay_single":
        # 单根因 NET: 只有 F1 delay, 无 F2(read_timeout)项。
        config.update({"net_delay_ms": NET_DELAY_MS, "net_jitter_ms": NET_JITTER_MS})
    elif fault == "net_loss_single":
        # 单根因 NET loss: 只有 F1 loss_pct, 无 delay/f2 键。
        config.update({"net_loss_pct": NET_LOSS_PCT})
    elif fault == "pod_failure_single":
        # 单根因 lifecycle/可用率: 只有 F1 pod-failure action, 无 NET/f2 键。
        config.update({"pod_failure_action": "pod-failure"})
    elif fault == "runtime_exception_single":
        # 单根因 M2b3 RUN: app env-hook 运行时异常(kubectl set env deploy/catalog FAULT_RAISE=1 → before_request raise → /api/* 500), 无 NET/f2 键。
        config.update({"fault_env_key": "FAULT_RAISE", "fault_env_value": "1"})
    elif fault == "dual_podfail_staggered":
        # 双根因 lifecycle staggered(M3d S4): F1 catalog pod-failure【前半窗】× F2 user pod-failure【后半窗】, midpoint=T/2 错峰。
        config.update({"pod_failure_action": "pod-failure", "f1_target": "catalog", "f2_target": "user",
                       "staggered_midpoint_offset_seconds": round(args.stage_seconds / 2.0, 3)})
    elif fault == "service_cpu_single":
        # 单根因 resource/per-service CPU: 只有 F1 StressChaos cpu(workers/load), 无 NET/f2 键。
        config.update({"stress_cpu_workers": STRESS_CPU_WORKERS, "stress_cpu_load": STRESS_CPU_LOAD,
                       "service_cpu_ratio_threshold": SERVICE_CPU_RATIO_THR})
    elif fault == "catalog_latency_single":
        # 单根因 rank[2] app env-hook 依赖延迟: F1 kubectl set env deploy/catalog FAULT_DELAY_MS=<ms> before_request sleep, carrier=catalog_direct, 无 NET/f2 键。
        config.update({"fault_env_key": "FAULT_DELAY_MS", "fault_env_value": str(args.cat_delay_ms),
                       "cat_delay_ms": args.cat_delay_ms,
                       "catlat_latency_margin_ms": INV_LATENCY_MARGIN_MS,
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None)})
    elif fault == "host_cpu_single":
        # 单根因 resource/off-graph host CPU 共因: F1 StressChaos cpu workers=12(stressor 无 limit 溢出整 VM), 多载体多受害者。
        config.update({"stress_host_workers": STRESS_HOST_WORKERS, "stress_host_load": STRESS_HOST_LOAD,
                       "host_cpu_ratio_threshold": HOST_CPU_RATIO_THR,
                       "carriers_spec": (args.carriers or "s1_hostcpu"),
                       "user_token": getattr(args, "user_token", None)})
    elif fault == "host_cpu_x_svccpu":
        # 双根因 combo(M3b-2, fault_masking): F1 host StressChaos workers=12 × F2 catalog StressChaos workers=2 nested(F1⊂F2, host 窗⊃catalog 窗)。
        config.update({"stress_host_workers": STRESS_HOST_WORKERS, "stress_host_load": STRESS_HOST_LOAD,
                       "stress_cpu_workers": STRESS_CPU_WORKERS, "stress_cpu_load": STRESS_CPU_LOAD,
                       "host_cpu_ratio_threshold": HOST_CPU_RATIO_THR, "throttle_eps": THROTTLE_EPS,
                       "carriers_spec": (args.carriers or "s1_hostcpu"),
                       "user_token": getattr(args, "user_token", None)})
    elif fault == "host_cpu_x_cfg_timeout":
        # 双根因 combo(DK09, nested trigger_amplifier): F1 host StressChaos workers=12(整 during) × F2 catalog-gw nginx conf(ov-hostcfg-f2.conf, nested 子窗)。
        #   合并 stress_host_workers/load + ratio_thr(host 族)+ f2_read_timeout_ms=所选 + f2_conf 路径 + carriers_spec=s1_hostcfg + user_token + catalog_direct_base。
        #   f2_offset/f2_duration 已在 base config(L5151-5153); calibration 20ms@69% err 稳健触发。
        config.update({"stress_host_workers": STRESS_HOST_WORKERS, "stress_host_load": STRESS_HOST_LOAD,
                       "host_cpu_ratio_threshold": HOST_CPU_RATIO_THR,
                       "f2_read_timeout_ms": HOSTCFG_F2_READ_TIMEOUT_MS, "f2_conf": HOSTCFG_F2_CONF,
                       "f1_timeout_baseline_ms": F1_TIMEOUT_BASELINE_MS,
                       "carriers_spec": (args.carriers or "s1_hostcfg"),
                       "user_token": getattr(args, "user_token", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None)})
    elif fault == "catalog_latency_x_cfg_timeout":
        # 双根因 combo(DK14, nested trigger_amplifier): F1 catlat FAULT_DELAY_MS(整 during) × F2 catalog-gw ov-catlat-f2.conf read_timeout 1000ms(nested 子窗)。
        #   f2_offset/f2_duration 已在 base config; catlat cat_delay_ms(默认 2000)> f2_read_timeout(1000)= 2× deterministic margin。
        config.update({"fault_env_key": "FAULT_DELAY_MS", "cat_delay_ms": args.cat_delay_ms,
                       "f2_read_timeout_ms": CATLAT_F2_READ_TIMEOUT_MS, "f2_conf": CATLAT_F2_CONF,
                       "f1_timeout_baseline_ms": F1_TIMEOUT_BASELINE_MS,
                       "catlat_iso_margin_ms": NET_ISO_MARGIN_MS,
                       "carriers_spec": (args.carriers or "s_dk14_catlat_cfg"),
                       "user_token": getattr(args, "user_token", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None)})
    elif fault == "catalog_latency_x_net_loss":
        # 双根因 combo(DK15, cross_class partial_overlap co_primary): F1 catlat FAULT_DELAY_MS(整 during, MID-during recover) × F2 catalog-gw egress netem net_loss 85%(NetworkChaos, mid-during 子窗)。
        #   ★LABEL 自纠: 上游标 amplifier 但 loss 不放大 latency, 实为 independent co_primary; per_root_B 用 error_ratio(loss 合法 error)。probe_timeout=3s 分离 catlat-slow vs loss-error。
        config.update({"fault_env_key": "FAULT_DELAY_MS", "cat_delay_ms": args.cat_delay_ms,
                       "net_loss_pct": NET_LOSS_DK15_PCT,
                       "net_loss_probe_timeout_sec": NET_LOSS_PROBE_TIMEOUT_SEC,
                       "catlat_iso_margin_ms": NET_ISO_MARGIN_MS,
                       "carriers_spec": (args.carriers or "s_dk15_catlat_loss"),
                       "user_token": getattr(args, "user_token", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None),
                       "labels_provisional": True})
    elif fault == "net_delay_x_svc_cpu":
        # 双根因 combo(DK17, cross_class SIMULTANEOUS independent_parallel co_primary): F1 catalog-gw egress netem net_delay(NetworkChaos)× F2 catalog service_cpu 饱和(StressChaos cpu workers=2)。
        #   ★两根正交(网络 latency vs CPU throttle)无放大; NET 根用绝对 p95 位移 / RES 根用 cfs_throttle(绝不用 gw/direct ratio 门)。
        config.update({"net_delay_ms": NET_DELAY_MS, "net_jitter_ms": NET_JITTER_MS,
                       "stress_cpu_workers": STRESS_CPU_WORKERS, "stress_cpu_load": STRESS_CPU_LOAD,
                       "net_iso_margin_ms": NET_ISO_MARGIN_MS, "throttle_eps": THROTTLE_EPS,
                       "disjoint_p95_ratio_max": DB_LOCK_DISJOINT_P95_RATIO_MAX,
                       "carriers_spec": (args.carriers or "s_dk17_netdelay_svccpu"),
                       "user_token": getattr(args, "user_token", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None),
                       "labels_provisional": True})
    elif fault == "catalog_latency_x_svc_cpu":
        # 双根因 combo(DK18, cross_class SIMULTANEOUS independent_parallel co_primary): F2 catalog app-latency(catlat FAULT_DELAY_MS, DEP OUTER) × F1 catalog service_cpu 饱和(StressChaos cpu workers=2, RES INNER)。
        #   ★★NO spatial control(两根同 catalog 同 latency 模态)→ 可分只靠 MECHANISM: catlat 用 catalog_direct 绝对 p95>=CATLAT_LATENCY_MARGIN_MS[1000](intensity-gap witness)/ svccpu 用 cfs_throttle>eps(marker)。labels PROVISIONAL。
        config.update({"fault_env_key": "FAULT_DELAY_MS", "cat_delay_ms": args.cat_delay_ms,
                       "stress_cpu_workers": STRESS_CPU_WORKERS, "stress_cpu_load": STRESS_CPU_LOAD,
                       "catlat_latency_margin_ms": CATLAT_LATENCY_MARGIN_MS, "throttle_eps": THROTTLE_EPS,
                       "disjoint_p95_ratio_max": DB_LOCK_DISJOINT_P95_RATIO_MAX,
                       "carriers_spec": (args.carriers or "s_dk18_catlat_svccpu"),
                       "user_token": getattr(args, "user_token", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None),
                       "spatial_control_absent": True, "mechanism_separability": True,
                       "labels_provisional": True})
    elif fault == "db_lock_single":
        # 单根因 resource/off-graph DB-lock 共因: F1 host-side DbContentionInjector LOCK TABLES items WRITE, 多载体 items-reader error-burst。
        config.update({"db_lock_table": DB_LOCK_TABLE, "db_lock_hold_sec": DB_LOCK_HOLD_SEC,
                       "db_lock_gap_sec": DB_LOCK_GAP_SEC, "db_lock_probe_timeout_sec": DB_LOCK_PROBE_TIMEOUT_SEC,
                       "db_lock_error_ratio_threshold": DB_LOCK_ERROR_RATIO_THR,
                       "db_lock_disjoint_p95_ratio_max": DB_LOCK_DISJOINT_P95_RATIO_MAX,
                       "carriers_spec": (args.carriers or "s2_dblock"),
                       "user_token": getattr(args, "user_token", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None)})
    elif fault == "db_lock_x_netdelay":
        # 双根因 combo(M3c-2, cross_class fault_masking): F1 items_lock(LOCK TABLES items WRITE) × F2 catalog-gw NET delay 同窗 co-active。
        config.update({"db_lock_table": DB_LOCK_TABLE, "db_lock_hold_sec": DB_LOCK_HOLD_SEC,
                       "db_lock_gap_sec": DB_LOCK_GAP_SEC, "db_lock_probe_timeout_sec": DB_LOCK_PROBE_TIMEOUT_SEC,
                       "db_lock_error_ratio_threshold": DB_LOCK_ERROR_RATIO_THR,
                       "db_lock_disjoint_p95_ratio_max": DB_LOCK_DISJOINT_P95_RATIO_MAX,
                       "net_delay_ms": NET_DELAY_MS, "net_jitter_ms": NET_JITTER_MS,
                       "net_sep_ms": NET_SEP_MS, "net_sep_ratio": NET_SEP_RATIO,
                       "carriers_spec": (args.carriers or "s2_dblock_combo"),
                       "user_token": getattr(args, "user_token", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None)})
    elif fault == "net_delay_x_cfg_connect":
        config.update({"net_delay_ms": NET_DELAY_MS, "net_jitter_ms": NET_JITTER_MS,
                       "f2_read_timeout_ms": F2_READ_TIMEOUT_MS})
    elif fault == "net_delay_x_inv_latency":
        # DK11 cross_class partial_overlap: F1=inventory app-latency(inv_delay_ms) × F2=catalog-gw netem net_delay。
        #   专用分支(不落 M1 else): 记 inv/net 强度 + partial_overlap 时序(f2_offset/f2_duration base 已含) + stage_seconds。
        config.update({"inv_delay_ms": (args.inv_delay_ms if args.inv_delay_ms is not None else 2000),  # ★FIX-5: 尊重显式 0(argparse 已默认 2000)
                       "net_delay_ms": NET_DELAY_MS, "net_jitter_ms": NET_JITTER_MS,
                       "inv_latency_margin_ms": INV_LATENCY_MARGIN_MS, "net_iso_margin_ms": NET_ISO_MARGIN_MS,
                       "inventory_direct_base": getattr(args, "inventory_direct_base", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None),
                       "carriers_spec": (args.carriers or "deep_dual_edge"),
                       "user_token": getattr(args, "user_token", None),
                       "cart_user_token": getattr(args, "cart_user_token", None)})
    elif fault == "net_delay_x_podfail":
        # DK05B cross_class STAGGERED: F1=catalog-gw netem net_delay【前半窗】 × F2=user pod-failure(可用性中断)【后半窗】, midpoint=T/2 错峰。
        config.update({"net_delay_ms": NET_DELAY_MS, "net_jitter_ms": NET_JITTER_MS,
                       "net_iso_margin_ms": NET_ISO_MARGIN_MS,
                       "pod_failure_action": "pod-failure", "f1_target": "catalog-gw", "f2_target": "user",
                       "staggered_midpoint_offset_seconds": round(args.stage_seconds / 2.0, 3),
                       "carriers_spec": (args.carriers or "s_netpod_cross"),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None),
                       "user_token": getattr(args, "user_token", None)})
    elif fault == "pod_failure_x_net_delay":
        # DK19 cross_class NESTED masking_compound(上游双-16): F1=catalog-gw netem net_delay【OUTER whole-during MASKED】 × F2=catalog pod-failure【INNER nested 子窗 MASKING】。
        #   ★两根 NOT simultaneously independently observable(overlap net masked by pod-failure availability)=masking_compound BY DESIGN; net 根从 F1_only clean 窗归因, pod-failure 根从 overlap availability 归因; labels PROVISIONAL。
        config.update({"net_delay_ms": NET_DELAY_MS, "net_jitter_ms": NET_JITTER_MS,
                       "net_iso_margin_ms": NET_ISO_MARGIN_MS,
                       "pod_failure_action": "pod-failure", "f1_target": "catalog-gw", "f2_target": "catalog",
                       "overlap_err_min": PODNET_OVERLAP_ERR_MIN, "overlap_success_floor": PODNET_OVERLAP_SUCCESS_FLOOR,
                       "disjoint_p95_ratio_max": DB_LOCK_DISJOINT_P95_RATIO_MAX,
                       "f2_offset_seconds": args.f2_offset_seconds, "f2_duration_seconds": args.f2_duration_seconds,
                       "carriers_spec": (args.carriers or "s_podfail_netdelay"),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None),
                       "user_token": getattr(args, "user_token", None),
                       "masking_by_design": True, "labels_provisional": True})
    elif fault == "sasrec_cpu_x_catalog_netdelay":
        # DK12 cross_class partial_overlap: F1=sasrec service_cpu(StressChaos workers=8, RATIO 判据) × F2=catalog-gw netem net_delay(绝对位移判据)。
        #   recommend_user_token 复用 cart_user_token(user_demo_001 有 SASRec 词表历史; != 分离载体 user_token); recommendations_deleted 计数由 main 经 gate_evidence 透传。
        config.update({"stress_cpu_workers": STRESS_SASREC_WORKERS, "stress_cpu_load": STRESS_CPU_LOAD,
                       "service_cpu_ratio_threshold": SERVICE_CPU_RATIO_THR,
                       "net_delay_ms": NET_DELAY_MS, "net_jitter_ms": NET_JITTER_MS,
                       "net_iso_margin_ms": NET_ISO_MARGIN_MS,
                       "carriers_spec": (args.carriers or "s_dk12_sasrec_net"),
                       "user_token": getattr(args, "user_token", None),
                       "cart_user_token": getattr(args, "cart_user_token", None),
                       "recommend_user_token": getattr(args, "cart_user_token", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None),
                       "recommendations_deleted": gate_evidence.get("recommendations_deleted")})
    elif fault == "inv_latency_x_runtime_exc":
        # DK13 cross_class SIMULTANEOUS: root_a=inventory app-latency(inv_delay_ms) × root_b=catalog runtime_exception(FAULT_RAISE=1 → HTTP 500)。
        config.update({"inv_delay_ms": (args.inv_delay_ms if args.inv_delay_ms is not None else 2000),  # ★尊重显式 0(argparse 默认 2000)
                       "runtime_fault_env": "FAULT_RAISE=1", "net": "N/A",
                       "inv_latency_margin_ms": INV_LATENCY_MARGIN_MS,
                       "db_lock_error_ratio_threshold": DB_LOCK_ERROR_RATIO_THR,
                       "db_lock_disjoint_p95_ratio_max": DB_LOCK_DISJOINT_P95_RATIO_MAX,
                       "carriers_spec": (args.carriers or "s_dk13_inv_run"),
                       "user_token": getattr(args, "user_token", None),
                       "catalog_direct_base": getattr(args, "catalog_direct_base", None),
                       "inventory_direct_base": getattr(args, "inventory_direct_base", None)})
    elif fault in G2EXT_COMBOS:
        # ★G2ext(B1 配套小修): 不落最终 else 的 M1 f1_timeout_* 键(对 g2ext 纯虚构); 按注册表如实落腿配置。
        _g2cfg = G2EXT_COMBOS[fault]
        config.update({
            # ★Phase B: workers 仅在腿显式带时入列(sasrec=8; Phase A 腿无 → 列表逐字节不变)。
            "g2ext_legs": [dict({"fid": _lg["fid"], "svc": _lg["svc"], "kind": _lg["kind"]},
                                **({"workers": _lg["workers"]} if "workers" in _lg else {}))
                           for _lg in _g2cfg["legs"]],
            "g2ext_timing": _g2cfg["timing"],
            "carriers_spec": (args.carriers or _g2cfg["carriers"]),
            "stress_cpu_workers": STRESS_CPU_WORKERS, "stress_cpu_load": STRESS_CPU_LOAD,
            "g2ext_podfail_dwell_max_s": G2EXT_PODFAIL_DWELL_MAX,
            "user_token": getattr(args, "user_token", None),
            "cart_user_token": getattr(args, "cart_user_token", None),
        })
        # ★Phase B 溯源追加(纯加法, Phase A 5 组无这些腿/键 → metadata 字节级不变):
        #   (a) rec-agent 腿(双-20) = G1 五件套之【metadata 溯源】g2ext 等价(镜像 L11141-11151 键集): 评测者由此知
        #       gate 判据来源 = recagent_health GET, recommend POST 只是证据通道。
        if any(_lg["svc"] == "rec-agent" for _lg in _g2cfg["legs"]):
            config.update({
                "recagent_gate_carrier": RECAGENT_GATE_CARRIER,
                "recagent_recommend_carrier": RECAGENT_RECOMMEND_CARRIER,
                "recagent_recommend_url": (getattr(args, "recagent_recommend_url", None)
                                           or "kubectl_proxy_8001_default(/services/rec-agent:5001/proxy/recommend)"),
                "recagent_seq": getattr(args, "recagent_seq", None),
                "recagent_top_k": getattr(args, "recagent_top_k", None),
                "recagent_recommend_timeout_s": getattr(args, "recagent_recommend_timeout", None),
                "recagent_recommend_db_writes": "none(rec-agent 无 DB; 无需 DK12 式 recommendations DELETE cleanup)",
            })
        #   (b) netdelay 腿(三-06 静态 catalog-gw / ★Phase C 三-07 渲染 rec-agent): 强度按腿如实(三-06 无 net_delay_ms 键
        #       → NET_DELAY_MS 逐字节不变; 三-07 有键 → 450/90)+ 判据门限。
        _nd_leg = next((_lg for _lg in _g2cfg["legs"] if _lg["kind"] == "netdelay"), None)
        if _nd_leg is not None:
            config.update({"net_delay_ms": _nd_leg.get("net_delay_ms", NET_DELAY_MS),
                           "net_jitter_ms": _nd_leg.get("net_jitter_ms", NET_JITTER_MS),
                           "net_iso_margin_ms": NET_ISO_MARGIN_MS,
                           "netdelay_leg_yaml": ("rendered_NetworkChaos(" + _nd_leg["svc"] + " egress, G1 定档; 无 control 臂)"
                                                 if "net_delay_ms" in _nd_leg
                                                 else "static_NET_F1_DELAY_YAML(catalog-gw egress netem, DK17/DK12 既有档)")})
        #   (c) ★Phase C invlat 腿(双-17): inventory dep-latency 强度 + 判据门限(gate 臂 = inventory_direct 绝对位移>=800)。
        if any(_lg.get("kind") == "invlat" for _lg in _g2cfg["legs"]):
            config.update({"inv_delay_ms": (args.inv_delay_ms if args.inv_delay_ms is not None else G2EXT_INVLAT_DELAY_MS),
                           "inv_latency_margin_ms": INV_LATENCY_MARGIN_MS,
                           "g2ext_invlat_min_tail_s": G2EXT_INVLAT_MIN_TAIL,
                           "invlat_leg_engine": "app_env_hook(kubectl set env FAULT_DELAY_MS, DK11 既有原语; staggered 晚窗)"})
        #   (d) recommend_probe(三-06/三-07): recommend buyer + per-case DELETE cleanup 计数(gate_evidence 透传, DK12 同款)。
        if _g2cfg.get("post_probe") == "recommend_probe":
            config.update({"recommend_user_token": getattr(args, "cart_user_token", None),
                           "recommendations_deleted": gate_evidence.get("recommendations_deleted")})
    else:
        config.update({"f1_timeout_short_ms": F1_TIMEOUT_SHORT_MS,
                       "f1_timeout_baseline_ms": F1_TIMEOUT_BASELINE_MS})

    # ★M9-R retarget: 仅 target != catalog 时【追加】3 个溯源键(默认 catalog 恒不进 → metadata.json 字节级零回归)。
    #   ★放在整条 if/elif 链【结束之后】(独立 if): 塞进链里会把后续 elif 重新挂到本 if 上 = 静默改结构。
    if _target_svc != "catalog":
        config.update({"target_service": _target_svc,
                       "target_app_label": RETARGET_APP_LABEL.get(_target_svc, _target_svc),
                       "carrier_route": "kubectl_proxy_8001_service_proxy(= probe-panel 同路由; 非 port-forward)"})
        # ★G1 rec-agent(2026-07-21): 双载体溯源(纯追加; 其它 retarget target 不进 → 字节级不变)。
        #   gate 判据只用 health 载体(recagent_gate_carrier), recommend POST 是业务证据通道 —— 评测者读此知判据来源。
        if _target_svc == "rec-agent":
            config.update({
                "recagent_gate_carrier": RECAGENT_GATE_CARRIER,
                "recagent_recommend_carrier": RECAGENT_RECOMMEND_CARRIER,
                "recagent_recommend_url": (getattr(args, "recagent_recommend_url", None)
                                           or "kubectl_proxy_8001_default(/services/rec-agent:5001/proxy/recommend)"),
                "recagent_seq": getattr(args, "recagent_seq", None),
                "recagent_top_k": getattr(args, "recagent_top_k", None),
                "recagent_recommend_timeout_s": getattr(args, "recagent_recommend_timeout", None),
                "recagent_recommend_db_writes": "none(rec-agent 无 DB; 无需 DK12 式 recommendations DELETE cleanup)",
            })

    # ---- metadata.json ----
    metadata = {
        "schema_version": SCHEMA_VERSION, "stage_layout": STAGE_LAYOUT,
        "sample_id": case_id, "run_id": run_id, "system": "recweb2",
        "platform": "kubernetes", "kubernetes_context": "docker-desktop",
        "chaos_engine": profile["chaos_engine_top"], "root_count": root_count,
        "category": profile["fault_category"], "composition_type": profile["composition_type"],
        "interaction_pattern": profile["interaction_pattern"], "path_relation": profile["path_relation"],
        "faults": [
            {"fault_instance_id": ci["fault_instance_id"], "fault_class": ci["fault_class"],
             "fault_type": ci["fault_type"], "injection_fault": ci["injection_fault"],
             "target_component": ci["target_component"], "target_container": ci.get("target_container"),
             "role": ci["role"], "injected_at": ci.get("injected_at"), "recovered_at": ci.get("recovered_at"),
             "status": "recovered", "component_ground_truth": ci}
            for ci in component_ground_truth
        ],
        "root_causes": profile["root_causes"],
        "component_fault_windows": component_fault_windows,
        "overlap_window": overlap_window,
        "observation_stages": obs_stages,
        "traffic_error_stats": traffic_error_stats,
        "validation_results": validation_results,
        "root_metric_contract": root_metric_contract,
        "isolation_check": isolation_check,          # NET case 单边隔离探针(M1=None)
        "isolation_degraded": isolation_degraded,    # must-fix#6: True=单边不 flat→降级 service-level cross_class
        "ground_truth": ground_truth,
        "artifacts": {
            "metrics": "raw/metrics/metrics_v2.jsonl",
            "traces": [f"raw/traces/{s}_traces.jsonl" for s in STAGE_LAYOUT],
            "logs": "raw/logs/", "operations": "raw/operations/injection.json",
            "groundtruth": "groundtruth.json", "summary": "summary.md",
        },
        "checksum_guard": {"pre": checksum_pre, "post": checksum_post,
                           "baseline": CHECKSUM_BASELINE,
                           "zero_drift": (checksum_pre == checksum_post == CHECKSUM_BASELINE)},
        "config": config,
        # must-fix#6: mr2 顶层字段（release-gate 由全 validation 过推导）
        "sample_status": "ready_for_release" if all_validation_pass else "blocked",
        "ready_for_release": all_validation_pass,
        "validation_complete": True,
        "trace_stats": {st["stage"]: {"total": trace_counts.get(st["stage"], 0)} for st in stages},
        "metric_schema_version": "metrics.v2",
        "storage_layout": "single_dir_stage_tagged",
        "formal_slot_id": case_id,
        "scenario_name": profile["scenario_name"],
        "phase": profile["phase"],
        "updated_at": now_iso(),
        "created_at": now_iso(),
    }
