def _safe_fmt(url, **kw):
    """安全占位替换(替 str.format, 防未提供占位 KeyError; 未提供的占位原样保留, 由调用方补)。"""
    for k, v in kw.items():
        if v is not None:
            url = url.replace("{" + k + "}", str(v))
    return url


def _parse_carriers(spec, item=None, user_token=None, search_q="phone", catalog_base=None, cart_user=None):
    """解析 --carriers: None/空→None(单载体现状, 字节级零回归); JSON 数组/对象→list; 预设名→CARRIER_PRESETS。
    返回 None 或 list of {name,url,role[,timeout]}(URL 占位已替换)。非法 spec 抛 ValueError(清晰报错不静默)。
    timeout 仅当 preset/JSON 显式给出才保留(s2_dblock items-reader 用; 未给出 → 不加键 → _capture_stage_multi 用 probe_carrier 默认 20s = 零回归)。"""
    if not spec:
        return None
    spec = spec.strip()
    if spec[:1] in ("[", "{"):
        raw = json.loads(spec)
        if isinstance(raw, dict):
            raw = [raw]
    elif spec in CARRIER_PRESETS:
        raw = CARRIER_PRESETS[spec]
    else:
        raise ValueError(f"--carriers 既非合法 JSON 也非预设名: {spec!r} (预设: {list(CARRIER_PRESETS)})")
    carriers = []
    for i, c in enumerate(raw):
        if "url" not in c:
            raise ValueError(f"--carriers 第 {i} 项缺 url: {c!r}")
        # GET-only 红线(O.2d must-fix#4): 载体一律只读 GET, 严禁带写语义键 method/body
        #   (防误引 cart POST /add、inventory POST /reserve、review 写端点 -> 破坏 items/inventory 只读铁律)。
        for _forbidden in ("method", "body"):
            if _forbidden in c:
                raise ValueError(
                    f"--carriers 第 {i} 项含禁用键 {_forbidden!r}（载体只读 GET 红线; 严禁写端点 method/body）: {c!r}")
        url = _safe_fmt(c["url"], item=item, user_token=user_token, search_q=search_q,
                        catalog_base=catalog_base, cart_user=cart_user)
        cc = {"name": c.get("name", f"carrier{i}"), "url": url, "role": c.get("role", "victim")}
        if c.get("timeout") is not None:
            cc["timeout"] = c["timeout"]   # 仅显式给出才加(host_cpu/单载体 carrier 不含此键 → 字节级零回归)
        carriers.append(cc)
    return carriers


def _dk12_delete_recommendations(token, phase, ops_log):
    """DK12 cleanup_spec: DELETE FROM recommendations WHERE user_token=<token>, then COUNT(*) 残留。返回 (deleted_rows, remaining_count)。
    ★FAIL-LOUD(非 calib_dk12_sasrec.py:149-151 的 -1 WARN-continue): DB 连接/DELETE/COUNT 任一异常 → 抛 → 由调用方决定 abort case / 标 fail(绝不静默 continue)。
    复用 runner host MySQL 常量(DB_HOST/PORT/USER/PASS/NAME = DbContentionInjector host-conn 同源 L1096-1097 / _confirm_items_unlocked)。
    ★理由: CHECKSUM 只护 items/inventory(设计排除 recommendations 因可重建, YAML L10 注)→ recommendations 静默失败会累积 rows 且 CHECKSUM 盲 → 必 per-case DELETE + row-count 断言。
    ★items/inventory 全程只读 CHECKSUM 三验铁律不变(本函数只碰 recommendations)。"""
    import mysql.connector
    cn = None
    try:
        cn = mysql.connector.connect(host=DB_HOST, port=DB_PORT, user=DB_USER,
                                     password=DB_PASS, database=DB_NAME, connection_timeout=10)
        cur = cn.cursor()
        cur.execute("DELETE FROM recommendations WHERE user_token=%s", (token,))
        deleted = cur.rowcount
        cn.commit()
        cur.execute("SELECT COUNT(*) FROM recommendations WHERE user_token=%s", (token,))
        remaining = int(cur.fetchone()[0])
        cur.close()
        ops_log.append({"ts": now_iso(), "op": f"dk12_cleanup_recommendations:{phase}",
                        "user_token": token, "deleted_rows": deleted, "remaining": remaining})
        print(f"  [dk12-cleanup:{phase}] DELETE recommendations user_token={token} -> {deleted} rows, remaining={remaining}", flush=True)
        return deleted, remaining
    finally:
        if cn is not None:
            try:
                cn.close()
            except Exception:
                pass


